			['id' => 259, 'title' => '{"es_AR": "SUGERENCIAS"}', 'body' => '{"es_AR": "* Juegue con el/la niñ@ a caminar sobre los talones de los pies en línea recta. *Pida al/a la niñ@ que salte con los dos pies, cayendo en el mismo lugar. *Motive al/a la niñ@ a lanzar una pelota hacia arriba y agarrarla nuevamente."}', 'extra_attributes' => NULL, 'created_at' => '2019-02-18 15:28:02', 'updated_at' => '2019-02-18 15:28:02', 'deleted_at' => NULL],
			['id' => 260, 'title' => '{"es_AR": "SUGERENCIAS"}', 'body' => '{"es_AR": "*Pida al/a la niñ@ que camine marcha atrás manteniendo el equilibrio. *Juegue con el/la niñ@ a saltar a la soga. *Incentive al/a la niñ@ a sacarse y ponerse una campera, sin ayuda."}', 'extra_attributes' => NULL, 'created_at' => '2019-02-18 15:28:02', 'updated_at' => '2019-02-18 15:28:02', 'deleted_at' => NULL],
